{
  "world_id": "wld_ring_seven",
  "name": "Ring Seven",
  "description": "A generation ship circles a starless route, its seven inhabited rings stacked around a central spine. The seventh ring has declared independence and severed the elevators that once bound the tiers together. With supplies stranded above and below, every message, meal, and rescue now depends on fragile service ducts and a disputed network of maintenance drones. The ship's old systems were designed to keep people alive, not to keep them united; their quiet safeguards are becoming weapons of delay. In the dim, pressurized corridors, both sides race to control the machinery that can reconnect the ship—or make separation permanent.",
  "locations": [
    {
      "id": "loc_seventh_crown",
      "name": "Seventh Crown",
      "description": "The outermost habitable ring, where orchard windows face the ship's rotating hull. Its assembly hall occupies a former seed vault, and the independence council meets beneath shelves of dormant crops."
    },
    {
      "id": "loc_elevator_well",
      "name": "The Blind Well",
      "description": "A vast elevator shaft stopped between tiers by severed power trunks. Its maintenance lights blink in a sequence that does not match any ship manual, and voices sometimes travel up its walls from empty platforms."
    },
    {
      "id": "loc_spine_archive",
      "name": "Spine Archive",
      "description": "A sealed records chamber in the central spine, holding original ship plans and generations of altered maintenance logs. Access requires the cooperation of operators on both sides of the fracture."
    },
    {
      "id": "loc_water_cistern",
      "name": "Blue Cistern",
      "description": "A reservoir and filtration garden on the sixth ring, now the narrowest point in the struggle. Its pumps can supply either neighboring tier, but the old allocation system will accept only one destination at a time."
    }
  ],
  "factions": [
    {
      "id": "fac_crown_council",
      "name": "Crown Assembly",
      "description": "Delegates who argue that the seventh ring can survive as a self-governing community. They control local food stores and insist that reconnecting the elevators without a treaty would restore the old hierarchy.",
      "location_ids": [
        "loc_seventh_crown"
      ]
    },
    {
      "id": "fac_spine_wardens",
      "name": "Spine Wardens",
      "description": "A cross-tier emergency corps trained to keep the ship's life-support systems stable. Their orders prioritize pressure, water, and air over political claims, even when that means refusing help to a trapped population.",
      "location_ids": [
        "loc_elevator_well",
        "loc_spine_archive"
      ]
    },
    {
      "id": "fac_sixth_compact",
      "name": "Sixth-Ring Compact",
      "description": "Cistern workers and neighborhood stewards who control the last reliable water junction between the separated rings. They will aid either side, but only if neither can claim permanent ownership of the pumps.",
      "location_ids": [
        "loc_water_cistern"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_rotational_gravity",
      "statement": "Artificial gravity comes from the ship's rotation; moving inward toward the spine weakens it, and the central shaft has almost none.",
      "category": "physics"
    },
    {
      "id": "rul_pressure_seals",
      "statement": "Every ring is divided into pressure sectors that seal automatically when sensors detect a breach.",
      "category": "technology"
    },
    {
      "id": "rul_elevator_interlock",
      "statement": "The elevators cannot move while any ring reports an unresolved pressure or load fault.",
      "category": "technology"
    },
    {
      "id": "rul_drone_choir",
      "statement": "Maintenance drones coordinate through short-range pulses; when isolated, they repeat their last assigned task rather than accepting new commands.",
      "category": "technology"
    },
    {
      "id": "rul_water_ledger",
      "statement": "The cistern allocation system records each pump transfer on a physical drum that cannot be edited from the ship network.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_seeded_departure",
      "name": "Departure Stores Sealed",
      "description": "Before launch, the ship's founders divided seed stock and repair tools among the rings, believing that no single tier should hold the means to restore the whole vessel.",
      "era": "Launch generation",
      "location_ids": [
        "loc_seventh_crown",
        "loc_spine_archive"
      ]
    },
    {
      "id": "evt_ledger_compromise",
      "name": "The Cistern Accord",
      "description": "After a ration dispute, workers installed the physical transfer drum and won the right to witness every change in water allocation.",
      "era": "Middle generations",
      "location_ids": [
        "loc_water_cistern"
      ]
    },
    {
      "id": "evt_unlogged_pulses",
      "name": "The Unlogged Sequence",
      "description": "Technicians found maintenance drones repeating a route through the elevator well that appeared nowhere in the official logs. The route ended at a sealed archive door.",
      "era": "Recent years",
      "location_ids": [
        "loc_elevator_well",
        "loc_spine_archive"
      ]
    },
    {
      "id": "evt_severance",
      "name": "The Severance",
      "description": "The seventh ring declared independence and cut its elevator trunks. The operation was precise enough to preserve pressure, but its timing left several lifts suspended between tiers.",
      "era": "Present crisis",
      "location_ids": [
        "loc_seventh_crown",
        "loc_elevator_well"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_reconnection",
      "name": "The Price of Reconnection",
      "description": "The Crown Assembly demands a treaty before the lifts are restored, while the Spine Wardens warn that delay could strand people beyond the reach of emergency care. A hidden route in the drone sequence may reveal who can reconnect the system without either side's consent.",
      "faction_ids": [
        "fac_crown_council",
        "fac_spine_wardens"
      ]
    },
    {
      "id": "cnf_water_choice",
      "name": "One Pump, Two Rings",
      "description": "The Sixth-Ring Compact can divert water to the seventh ring or preserve supply to the lower tiers, but the physical ledger will make the choice public and permanent. Both larger factions are pressuring the stewards to decide before the cistern reserve falls.",
      "faction_ids": [
        "fac_crown_council",
        "fac_spine_wardens",
        "fac_sixth_compact"
      ]
    }
  ]
}

