response.output:
{
  "world_id": "wld_abyssal_courts",
  "name": "The Bellward Deep",
  "description": "Far below the sun, a city of merchants and nobles occupies the nave, crypts, and flooded cloisters of a drowned cathedral. Its air-filled halls survive beneath the trench’s crushing water through old warding rites and the careful tending of pressure-seals. Here, contracts carry more weight than bloodlines: the cathedral bells can make a broken oath literally weigh upon its maker, and every faction seeks to turn that strange law to its advantage. Mysterious chimes travel through the dark water, sometimes answering questions no living bell-ringer has asked.",
  "locations": [
    {
      "id": "loc_high_nave",
      "name": "The High Nave",
      "description": "The cathedral’s central hall, held dry by a ring of ancient seals. Merchant houses crowd its pillars with stalls and counting rooms, while noble balconies overlook the market."
    },
    {
      "id": "loc_bell_tower",
      "name": "The Bell Tower",
      "description": "A cracked spire rising into the trench water above the roof. Its great bronze bells ring without ropes when an oath is broken, though no two witnesses agree on what they heard."
    },
    {
      "id": "loc_salt_crypt",
      "name": "The Salt Crypt",
      "description": "A maze of burial niches where salt crystals preserve names and sealed wills. The quietest route between the noble houses, it is also where missing heirs are rumored to leave messages."
    },
    {
      "id": "loc_west_cloister",
      "name": "The West Cloister",
      "description": "A flooded arcade lit by pale anemones. Couriers pass through its submerged arches wearing breathing charms, and discreet meetings take place in its dry confession booths."
    },
    {
      "id": "loc_founders_choir",
      "name": "The Founders' Choir",
      "description": "A sealed chamber behind the altar, lined with stone seats bearing the names of the first settlers. A hairline leak pulses in time with the bells, threatening the wards that keep the city habitable."
    }
  ],
  "factions": [
    {
      "id": "fac_gilt_ledger",
      "name": "The Gilt Ledger",
      "description": "A merchant compact that controls food stores, repair crews, and most contracts in the nave. Its members want the bell-law made enforceable in every bargain.",
      "location_ids": ["loc_high_nave", "loc_west_cloister"]
    },
    {
      "id": "fac_house_vell",
      "name": "House Vell",
      "description": "An old noble line claiming descent from the cathedral’s founders. It keeps private genealogies in the crypt and insists that only its blood can renew the city’s seals.",
      "location_ids": ["loc_salt_crypt", "loc_founders_choir"]
    },
    {
      "id": "fac_bellwardens",
      "name": "The Bellwardens",
      "description": "A small order of keepers who tend the tower and interpret its unsummoned chimes. They conceal the fact that the bells have begun answering from beneath the cathedral, not above it.",
      "location_ids": ["loc_bell_tower", "loc_founders_choir"]
    }
  ],
  "rules": [
    {
      "id": "rul_pressure_seals",
      "statement": "The cathedral’s air halls remain habitable only while their pressure-seals are intact and regularly tended.",
      "category": "physics"
    },
    {
      "id": "rul_breathing_charms",
      "statement": "Outside a sealed hall, a breathing charm can sustain a person underwater, but only for a short passage.",
      "category": "technology"
    },
    {
      "id": "rul_broken_oaths",
      "statement": "When a sworn promise is knowingly broken within hearing of the bells, the oath-breaker bears a growing weight that only confession or fulfillment can lift.",
      "category": "metaphysics"
    },
    {
      "id": "rul_names_in_salt",
      "statement": "A name recorded in the crypt salt cannot be erased by ordinary means, though the record can be hidden or disputed.",
      "category": "metaphysics"
    },
    {
      "id": "rul_open_accounts",
      "statement": "No house may claim the right to renew the seals without witnesses from outside its own faction.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_last_sinking",
      "name": "The Last Sinking",
      "description": "A trench quake dragged the cathedral beneath the sea. Survivors sealed its nave and cloisters, then discovered that the bronze bells still rang through the water.",
      "era": "Founding Years",
      "location_ids": ["loc_high_nave", "loc_bell_tower"]
    },
    {
      "id": "evt_first_weight",
      "name": "The First Weighted Oath",
      "description": "A merchant who swore to share the last air stores and secretly hoarded them was pinned to the nave floor by an invisible weight. The survivors made sworn contracts the foundation of civic law.",
      "era": "Years of Hunger",
      "location_ids": ["loc_high_nave"]
    },
    {
      "id": "evt_vell_claim",
      "name": "The Vell Claim",
      "description": "House Vell produced a salt-preserved genealogy naming its ancestor as the cathedral’s first keeper. The claim secured the family a seat near the seal chambers but was never independently verified.",
      "era": "Rise of the Houses",
      "location_ids": ["loc_salt_crypt", "loc_founders_choir"]
    },
    {
      "id": "evt_answer_below",
      "name": "The Answer Below",
      "description": "During a silent watch, the tower bells rang from beneath the foundations. The wardens concealed the event; since then, the Founders' Choir has developed a pulsing leak.",
      "era": "The Present Chime",
      "location_ids": ["loc_bell_tower", "loc_founders_choir"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_seal_succession",
      "name": "Who May Renew the Seals",
      "description": "House Vell claims its bloodline alone can mend the wards, while the Gilt Ledger demands a witnessed vote and control of the repair funds. The leak makes delay dangerous, and each side suspects the other is hiding evidence in the crypt.",
      "faction_ids": ["fac_gilt_ledger", "fac_house_vell", "fac_bellwardens"]
    },
    {
      "id": "cnf_true_chime",
      "name": "The Bell's Hidden Voice",
      "description": "The Bellwardens want to learn what is ringing beneath the cathedral; the nobles fear that discovery could invalidate their founding claims, while merchants fear any new oath-law could ruin existing debts.",
      "faction_ids": ["fac_bellwardens", "fac_house_vell", "fac_gilt_ledger"]
    }
  ]
}

