{
  "world_id": "wld_velisca",
  "name": "The Veiled Reach",
  "description": "Velisca is a canal city of pale stone, mirrored water, and candlelit bridges, where an annual carnival lets citizens trade names as freely as dances. On the eve of its final procession, a foreign diplomat is found dead in a canal-side palazzo. Every guest wore a mask, and each insists the face they saw belonged to someone else. In this elegant mystery, old civic bargains and private loyalties matter as much as the clues left behind.",
  "locations": [
    {
      "id": "loc_lantern_quay",
      "name": "Lantern Quay",
      "description": "A narrow landing where the canal bends beneath a bridge of green marble. During the carnival, floating lanterns mark the official route; one dark gap in their line offers a quiet place to leave or retrieve a small object."
    },
    {
      "id": "loc_palazzo_serein",
      "name": "Palazzo Serein",
      "description": "The diplomat's canal-side residence, built around a dry courtyard and a private landing. Its reception hall has mirrored panels that reflect masked guests in a slightly different arrangement from the room itself."
    },
    {
      "id": "loc_echo_archive",
      "name": "The Echo Archive",
      "description": "A records house of blue-tiled chambers where clerks preserve signed agreements and the names used by their witnesses. Its oldest shelves stand below the canal level, and their ledgers bear watermarks from a flood no one can explain."
    }
  ],
  "factions": [
    {
      "id": "fac_canal_watch",
      "name": "Canal Watch",
      "description": "The wardens who patrol bridges and landings during the carnival. Their duty is to keep the waterways open, but their captain also guards a sealed route map that could place any reveler at the palazzo.",
      "location_ids": [
        "loc_lantern_quay",
        "loc_palazzo_serein"
      ]
    },
    {
      "id": "fac_serein_house",
      "name": "House Serein",
      "description": "The diplomat's hosts, a family whose influence rests on discreet hospitality and a web of debts owed by visiting envoys. They insist the palazzo's mirrored hall was empty when the body was found.",
      "location_ids": [
        "loc_palazzo_serein"
      ]
    },
    {
      "id": "fac_echo_clerks",
      "name": "Keepers of the Echo",
      "description": "Archivists sworn to preserve the city's agreements without judging them. Several clerks believe the diplomat came to alter a record; others fear that exposing the truth would dissolve the civic peace.",
      "location_ids": [
        "loc_echo_archive"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_name_exchange",
      "statement": "During the carnival, a person wearing a mask may claim another name, but any promise made under that claimed name remains binding on the speaker until dawn.",
      "category": "social"
    },
    {
      "id": "rul_canal_tide",
      "statement": "The city's canals rise and fall with the distant lagoon, and no gate or vessel can hold the water at a chosen level.",
      "category": "physics"
    },
    {
      "id": "rul_archive_witness",
      "statement": "An agreement entered in the Echo Archive is valid only if its witnesses sign with the names they used when the promise was spoken.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_silent_flood",
      "name": "The Silent Flood",
      "description": "Generations ago, the lagoon rose without rain and filled the lower archive. The city survived by recording every emergency pledge made that night; later rulers built the carnival around the custom of masked names and binding promises.",
      "era": "Founding era",
      "location_ids": [
        "loc_echo_archive",
        "loc_lantern_quay"
      ]
    },
    {
      "id": "evt_envoy_arrival",
      "name": "The Envoy's Arrival",
      "description": "The diplomat arrived with a sealed request to inspect an old civic agreement. House Serein hosted a private supper, while the Canal Watch altered its patrol pattern for the procession.",
      "era": "Present carnival",
      "location_ids": [
        "loc_palazzo_serein",
        "loc_echo_archive",
        "loc_lantern_quay"
      ]
    },
    {
      "id": "evt_body_discovered",
      "name": "The Last Reflection",
      "description": "At first light, a boatman found the diplomat in the water beside the palazzo. A guest's mask lay on the landing, but its inner lining carried a name that no one in the household would admit to recognizing.",
      "era": "Present carnival",
      "location_ids": [
        "loc_palazzo_serein",
        "loc_lantern_quay"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_missing_agreement",
      "name": "The Missing Agreement",
      "description": "House Serein wants the diplomat's inquiry buried, while the Keepers of the Echo insist the relevant ledger has been removed. The Canal Watch holds the only complete patrol record, but releasing it may expose one of its own wardens.",
      "faction_ids": [
        "fac_serein_house",
        "fac_echo_clerks",
        "fac_canal_watch"
      ]
    },
    {
      "id": "cnf_name_debt",
      "name": "A Name Owed",
      "description": "A promise made during the masked supper may bind its speaker to a crime they did not commit. The archivists seek the exact words, while the hosts and wardens each have reason to keep the speaker's borrowed name secret.",
      "faction_ids": [
        "fac_serein_house",
        "fac_echo_clerks",
        "fac_canal_watch"
      ]
    }
  ]
}

