response.output:
{
  "world_id": "wld_blackwood_asylum",
  "name": "The Blackwood Ward",
  "description": "At the end of a rain-cut mountain road stands Blackwood Asylum, a remote institution where every patient reports the same impossible dream: a corridor beneath a black lake, ending at a door that opens inward into the dreamer’s own room. A newly arrived psychiatrist is expected to classify the reports, restore order, and leave. Instead, clinical records begin to change between readings, and the staff find details in the dream that none of them have disclosed. Blackwood’s enclosed routines offer a precise vocabulary for fear, but no reliable boundary between observation and contagion.",
  "locations": [
    {
      "id": "loc_blackwood_asylum",
      "name": "Blackwood Asylum",
      "description": "A stone institution set above a ravine, reachable by a single switchback road. Its windows are shuttered against the surrounding fog, and its wards are arranged around a locked hydrotherapy level that does not appear on the current floor plans. Patients and staff alike report a low, measured knocking from beneath the building."
    }
  ],
  "factions": [
    {
      "id": "fac_medical_directorate",
      "name": "Medical Directorate",
      "description": "The asylum’s senior clinicians, committed to keeping symptoms legible and the institution operational. They insist that the shared dream is a form of suggestion, though their private case notes contain matching descriptions written years apart.",
      "location_ids": ["loc_blackwood_asylum"]
    },
    {
      "id": "fac_sleeping_circle",
      "name": "The Sleeping Circle",
      "description": "A loose alliance of patients who compare dream details in secret. They believe the corridor is not a symbol but a route, and that one of them must remember the door’s handle before the next communal sleep.",
      "location_ids": ["loc_blackwood_asylum"]
    }
  ],
  "rules": [
    {
      "id": "rul_shared_dream",
      "statement": "Every person who sleeps inside the asylum eventually dreams of the corridor beneath the black lake, though each first remembers it as a private dream.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_witness",
      "statement": "No two sleepers can describe the same moment of the corridor while awake; their accounts align only after both have slept again.",
      "category": "metaphysics"
    },
    {
      "id": "rul_records",
      "statement": "A written account made after a dream may change once, but only to include a detail its author could not knowingly have observed.",
      "category": "other"
    },
    {
      "id": "rul_sleep_protocol",
      "statement": "Staff must not wake a patient during a shared-dream episode unless breathing or pulse is in immediate danger.",
      "category": "social"
    },
    {
      "id": "rul_clinical_language",
      "statement": "The Directorate classifies the dream as a symptom in every official chart, regardless of the patient’s account or the clinician’s private judgment.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_report",
      "name": "The First Matching Accounts",
      "description": "During an overnight observation, three patients in separate rooms described the same submerged corridor. Their sketches differed in every detail except the inward-opening door.",
      "era": "Founding years",
      "location_ids": ["loc_blackwood_asylum"]
    },
    {
      "id": "evt_missing_level",
      "name": "The Sealed Hydrotherapy Level",
      "description": "After a pipe failure, workers uncovered a stair beneath the hydrotherapy room. The Directorate sealed it within hours; the revised plans omit the stair, while older plans show a level with no recorded entrance.",
      "era": "A decade before the psychiatrist’s arrival",
      "location_ids": ["loc_blackwood_asylum"]
    },
    {
      "id": "evt_midnight_round",
      "name": "The Unlogged Round",
      "description": "A night nurse reported finding every sleeping patient standing beside a bed in the same posture. The incident vanished from the official ledger, but a carbon copy remains in the ward archive with the nurse’s name erased.",
      "era": "Recent years",
      "location_ids": ["loc_blackwood_asylum"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_classification",
      "name": "Symptom or Route",
      "description": "The Medical Directorate wants the shared dream contained within diagnosis and procedure; the Sleeping Circle wants to test whether its corridor leads somewhere real. If the Circle persuades the new psychiatrist to join them, the Directorate may suppress the evidence—or force a dangerous experiment before anyone understands what the dream demands.",
      "faction_ids": ["fac_medical_directorate", "fac_sleeping_circle"]
    }
  ]
}

