      "description": "The land baron's company, backed by hired guards and a tangle of bought surveys. It seeks exclusive control of the railway and the wells that make settlement possible.",
      "location_ids": ["loc_sable_junction", "loc_brineglass_flats"]
    }
  ],
  "rules": [
    {
      "id": "rul_water_rail",
      "statement": "A recorded rail deed grants passage over the track, but never ownership of the wells beside it.",
      "category": "social"
    },
    {
      "id": "rul_salt_bed",
      "statement": "The buried salt beds shift after heavy rain, so a boundary marked on dry ground can move before the next survey.",
      "category": "physics"
    },
    {
      "id": "rul_signal_echo",
      "statement": "The old signal cable carries a warning only while the locomotive's wheels remain on connected rail.",
      "category": "technology"
    },
    {
      "id": "rul_cistern_voice",
      "statement": "A spoken message at the Well of Nine Echoes can be heard through its conduits, but the chambers repeat each phrase nine times.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_first_spike",
      "name": "The First Spike",
      "description": "Track crews drove the first rail spike beside the shared cistern and agreed that water rights would remain communal, even as towns grew along the line.",
      "era": "Founding years",
      "location_ids": ["loc_sable_junction", "loc_well_of_nine_echoes"]
    },
    {
      "id": "evt_white_claim",
      "name": "The White Claim",
      "description": "After a storm exposed old survey stakes in the salt flats, Meridian Holdings declared the newly visible ground its private estate. The Drywell Union disputed the claim, and the Ironward Marshals began keeping the conflicting maps.",
      "era": "The survey dispute",
      "location_ids": ["loc_brineglass_flats", "loc_sable_junction"]
    },
    {
      "id": "evt_midnight_switch",
      "name": "The Midnight Switch",
      "description": "A locomotive vanished from the junction's yard during a staged transfer. The baron blamed the Union, while a marshal found the switching order had been altered before the train left.",
      "era": "The night of the theft",
      "location_ids": ["loc_sable_junction"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_water_deed",
      "name": "The Water Deed",
      "description": "Meridian Holdings wants to turn its disputed rail claim into control of the wells. The Drywell Union resists, while the Ironward Marshals struggle to enforce the law without legitimizing forged maps.",
      "faction_ids": ["fac_drywell_union", "fac_meridian_holdings", "fac_ironward"]
    },
    {
      "id": "cnf_stolen_engine",
      "name": "The Stolen Engine",
      "description": "The marshal needs the locomotive returned under lawful custody; the con artist needs it moving long enough to expose who altered the transfer order. Meridian's guards are closing in, and the Union risks losing the route if the train stops.",
      "faction_ids": ["fac_ironward", "fac_drywell_union", "fac_meridian_holdings"]
    }
  ]
}

