{
  "world_id": "wld_salt_meridian",
  "name": "The Salt Meridian",
  "description": "A stoic maritime world of rival crowns, wind-scoured islands, and disciplined fleets, where victory comes through seamanship, blockade, boarding, and the patience to outlast an enemy. In a war between the Crown of Veyra and the Lyran Compact, a Veyran naval officer learns that the opposing admiral is his estranged brother. Their private fracture threatens to expose old loyalties at the very moment both sides depend on them. Here, charts are political instruments: the fleet that controls the tide stations can make a safe passage vanish from every official map.",
  "locations": [
    {
      "id": "loc_veyra_roadstead",
      "name": "Veyra Roadstead",
      "description": "A sheltered harbor below the Veyran capital, crowded with repair yards, signal towers, and ships awaiting orders."
    },
    {
      "id": "loc_cinder_keys",
      "name": "Cinder Keys",
      "description": "A low chain of black-rock islands where hidden coves offer refuge to small craft and lookout posts command the surrounding channels."
    },
    {
      "id": "loc_morrow_sound",
      "name": "Morrow Sound",
      "description": "A narrow, fog-prone passage between steep shores. Its shifting currents punish captains who trust outdated charts."
    },
    {
      "id": "loc_tidehouse",
      "name": "The Tidehouse",
      "description": "A fortified station on a bare headland, where keepers record water levels and maintain a line of bronze sea bells used to mark safe channels."
    },
    {
      "id": "loc_lyran_quay",
      "name": "Lyran Quay",
      "description": "The Compact's chief naval harbor, built around a deep basin and a council hall where merchants and admirals bargain over every sailing."
    }
  ],
  "factions": [
    {
      "id": "fac_veyra_crown",
      "name": "Veyran Crown Fleet",
      "description": "A royal service built on strict logs, drilled crews, and the belief that a captain's duty ends only when the last vessel is accounted for.",
      "location_ids": [
        "loc_veyra_roadstead",
        "loc_tidehouse"
      ]
    },
    {
      "id": "fac_lyran_compact",
      "name": "Lyran Compact",
      "description": "A coalition of port cities whose fleet answers to elected councils as well as its admiral, making its strategy formidable but never entirely predictable.",
      "location_ids": [
        "loc_lyran_quay",
        "loc_cinder_keys"
      ]
    },
    {
      "id": "fac_soundwardens",
      "name": "Soundwardens",
      "description": "A hereditary guild of pilots and bell keepers who preserve local tide records. They sell no chart without recording who bought it.",
      "location_ids": [
        "loc_tidehouse",
        "loc_morrow_sound"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_sail_power",
      "statement": "Ships travel by sail, oar, and human labor; no engine can carry a vessel against the open sea.",
      "category": "technology"
    },
    {
      "id": "rul_signal_reach",
      "statement": "Flags and lamps carry orders only when weather, distance, and line of sight permit; a fleet at sea must often act on a captain's judgment.",
      "category": "technology"
    },
    {
      "id": "rul_tide_records",
      "statement": "Tide stations record local water and current conditions, but those records are useful only when matched to the correct season and channel.",
      "category": "other"
    },
    {
      "id": "rul_council_levy",
      "statement": "The Lyran Compact may levy ships from member ports, but each port can demand a public accounting before renewing its contribution.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_sound_chart",
      "name": "The First Sound Chart",
      "description": "Soundwardens joined scattered pilot ledgers into a common chart, making regular passage through the islands possible and giving the guild lasting influence.",
      "era": "Before the Crown War",
      "location_ids": [
        "loc_morrow_sound",
        "loc_tidehouse"
      ]
    },
    {
      "id": "evt_compact_formed",
      "name": "The Harbor Compact",
      "description": "After a royal tariff threatened several ports at once, the cities of Lyran bound themselves to mutual defense and built a shared fleet.",
      "era": "Thirty years before the war",
      "location_ids": [
        "loc_lyran_quay"
      ]
    },
    {
      "id": "evt_brothers_divide",
      "name": "The Sealed Passage",
      "description": "Two Veyran-born brothers disputed whether a hidden channel should be surrendered to the Crown. One left the service; years later, he rose to command the Lyran fleet.",
      "era": "Seven years before the war",
      "location_ids": [
        "loc_cinder_keys",
        "loc_veyra_roadstead"
      ]
    },
    {
      "id": "evt_war_begins",
      "name": "The Blockade of Morrow",
      "description": "The Compact closed Morrow Sound to Veyran shipping. The Crown answered with a fleet, beginning a war of patrols, interrupted supply lines, and contested charts.",
      "era": "Present war",
      "location_ids": [
        "loc_morrow_sound",
        "loc_veyra_roadstead",
        "loc_lyran_quay"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_brother_admirals",
      "name": "The Brothers' Line",
      "description": "The Veyran officer must oppose an admiral who knows his habits and history. Any private attempt at contact could be mistaken for treason by either fleet.",
      "faction_ids": [
        "fac_veyra_crown",
        "fac_lyran_compact"
      ]
    },
    {
      "id": "cnf_chart_ownership",
      "name": "Who Owns the Channel",
      "description": "The Soundwardens hold tide records that could break the blockade, but releasing them would expose which side has secretly altered the official charts.",
      "faction_ids": [
        "fac_soundwardens",
        "fac_veyra_crown",
        "fac_lyran_compact"
      ]
    },
    {
      "id": "cnf_council_supply",
      "name": "The Cost of Keeping Sea",
      "description": "Lyran ports disagree over how long to fund the blockade. A failed campaign could fracture the Compact; a successful one could leave the smaller ports unable to feed themselves.",
      "faction_ids": [
        "fac_lyran_compact",
        "fac_soundwardens"
      ]
    }
  ]
}

