{
  "world_id": "wld_yesterglass",
  "name": "The Yesterday Country",
  "description": "The Yesterday Country is a whimsical realm where time leaves its footprints in ordinary places: yesterday's rain gathers beneath bridges, old laughter drifts through orchards, and forgotten errands sometimes return wearing muddy boots. In a crooked house at the edge of the village, a child discovers a blue door that opens onto the very same place one day earlier. The door offers a chance to mend small mistakes, but every visit loosens a memory from the present. Now the child must decide what is worth changing while two groups argue over who should be allowed to cross.",
  "locations": [
    {
      "id": "loc_crooked_house",
      "name": "The Crooked House",
      "description": "A narrow, cheerful house leaning as if it is listening to the hill. Its blue pantry door opens onto yesterday, always into the room it would have faced one day before."
    },
    {
      "id": "loc_mallowmere",
      "name": "Mallowmere",
      "description": "A village of honey-colored roofs beside a pond where lily pads drift toward the conversations they most want to hear."
    },
    {
      "id": "loc_yesterday_bridge",
      "name": "Yesterday Bridge",
      "description": "A stone bridge that carries a faint echo of each footstep made across it the previous day. Its central stone is warm at dawn, even in winter."
    },
    {
      "id": "loc_clockwork_orchard",
      "name": "The Clockwork Orchard",
      "description": "An orchard of pear trees whose fruit ripens in the order of the birthdays spoken beneath their branches. A brass windmill at its center turns backward when someone lies about the past."
    },
    {
      "id": "loc_lost_things_fair",
      "name": "The Fair of Lost Things",
      "description": "A traveling market that appears in a different meadow each Thursday, selling misplaced buttons, unfinished songs, and objects people meant to remember."
    }
  ],
  "factions": [
    {
      "id": "fac_morrowkeepers",
      "name": "The Morrowkeepers",
      "description": "A kindly but stubborn circle of villagers who guard the blue door and believe yesterday should be visited only to prevent harm, never to improve anyone's fortunes.",
      "location_ids": [
        "loc_crooked_house",
        "loc_mallowmere"
      ]
    },
    {
      "id": "fac_second_chance",
      "name": "The Second-Chance Company",
      "description": "A band of traveling fixers who trade in yesterday's opportunities. They want to use the door to retrieve lost inventions and settle old bargains, insisting that a repaired past can make a brighter present.",
      "location_ids": [
        "loc_lost_things_fair",
        "loc_clockwork_orchard"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_door_day",
      "statement": "The blue door opens only onto the same place exactly one day earlier, and it closes at the first midnight either side experiences.",
      "category": "metaphysics"
    },
    {
      "id": "rul_memory_toll",
      "statement": "Each crossing loosens one small present-day memory from the traveler; the memory becomes a paper moth and flutters somewhere in the Yesterday Country.",
      "category": "metaphysics"
    },
    {
      "id": "rul_echo_cannot_speak",
      "statement": "A person encountered in yesterday remembers nothing of a later visitor, though objects moved by that visitor remain changed when the day catches up.",
      "category": "metaphysics"
    },
    {
      "id": "rul_lily_truth",
      "statement": "The lily pads of Mallowmere drift toward the speaker who is hiding the most important fact in a conversation.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_first_blue_day",
      "name": "The First Blue Day",
      "description": "Long ago, a storm blew the pantry door from its hinges. When the villagers rehung it, the open doorway showed their kitchen on the previous day, complete with a bowl of soup nobody had cooked yet.",
      "era": "Before the village bell was built",
      "location_ids": [
        "loc_crooked_house",
        "loc_mallowmere"
      ]
    },
    {
      "id": "evt_paper_moth_summer",
      "name": "The Summer of Moths",
      "description": "Several curious villagers crossed the door to rescue a lost picnic. They returned with the picnic, but their paper-moth memories filled the orchard and were gathered by children into lanterns.",
      "era": "The summer after the First Blue Day",
      "location_ids": [
        "loc_crooked_house",
        "loc_clockwork_orchard"
      ]
    },
    {
      "id": "evt_market_bargain",
      "name": "The Bargain at the Fair",
      "description": "The traveling fixers offered to recover the village bell's missing clapper from yesterday. The Morrowkeepers refused, fearing the cost; since then, both groups have watched the door and argued over the right to use it.",
      "era": "Three summers ago",
      "location_ids": [
        "loc_lost_things_fair",
        "loc_yesterday_bridge"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_who_may_return",
      "name": "Who May Return",
      "description": "The Morrowkeepers want the door kept shut except in emergencies, while the Second-Chance Company wants to cross freely and reclaim lost chances. The child's discovery gives both sides a reason to act before the next midnight.",
      "faction_ids": [
        "fac_morrowkeepers",
        "fac_second_chance"
      ]
    }
  ]
}

