response.output:
{
  "world_id": "wld_ashen_reach",
  "name": "The Ashen Reach",
  "description": "The Ashen Reach is a melancholy fantasy realm shaped by the absence of the great sky-beasts its ancestors once revered. Their bones mark old roads, their names have been scraped from public records, and whole trades have withered for want of their fire. Now a hidden egg has hatched in a country that remembers how to hunt, but not how to live beside what it hunted. Its small, uncertain life may restore a lost bond—or give old powers a reason to repeat their worst mistake.",
  "locations": [
    {
      "id": "loc_cinder_steps",
      "name": "Cinder Steps",
      "description": "A stair-cut mountain pass paved with dark scales, each tile set face down by decree. Travelers leave offerings in the cracks, though no one agrees who might receive them."
    },
    {
      "id": "loc_morrowfen",
      "name": "Morrowfen",
      "description": "A reed-choked wetland where pale lights drift above drowned orchards. A keeper's hut stands on stilts, its cellar newly warmed by a hatched egg."
    },
    {
      "id": "loc_salt_archive",
      "name": "The Salt Archive",
      "description": "A former lighthouse converted into a vault for outlawed maps and testimony. Salt seeps through its walls, preserving some pages while slowly eating others."
    },
    {
      "id": "loc_bellwether",
      "name": "Bellwether",
      "description": "A market town whose bronze bells once warned of shapes crossing the sun. Their clappers were removed generations ago; the silent towers now serve as lookout posts."
    },
    {
      "id": "loc_hollow_crown",
      "name": "Hollow Crown",
      "description": "A ring of high cliffs around a basin of black grass. Warm air rises from fissures in the earth, and the oldest local songs say the hills are listening."
    }
  ],
  "factions": [
    {
      "id": "fac_ashwardens",
      "name": "The Ashwardens",
      "description": "Descendants of the celebrated hunters, they guard the old passes and teach that mercy toward the sky-beasts once doomed whole provinces. Some now doubt the story they inherited.",
      "location_ids": [
        "loc_cinder_steps",
        "loc_bellwether"
      ]
    },
    {
      "id": "fac_lantern_scribes",
      "name": "The Lantern Scribes",
      "description": "A clandestine circle that collects forbidden songs, maps, and witness accounts. They believe the realm's missing history matters more than any throne's permission.",
      "location_ids": [
        "loc_salt_archive",
        "loc_morrowfen"
      ]
    },
    {
      "id": "fac_fenkeepers",
      "name": "The Fenkeepers",
      "description": "A small community of marsh stewards who bargain with flood, peat, and rumor. They shelter the newly hatched creature, but disagree on whether hiding it is protection or another kind of imprisonment.",
      "location_ids": [
        "loc_morrowfen",
        "loc_hollow_crown"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_warmstone",
      "statement": "Stone that has sheltered a living sky-beast keeps warmth through the coldest night, even after its guest is gone.",
      "category": "metaphysics"
    },
    {
      "id": "rul_namesake",
      "statement": "A creature's true name cannot be written by a hand that has never heard it spoken aloud.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bell_silence",
      "statement": "A bronze warning bell rings only when its clapper is freely given back by the person who removed it.",
      "category": "other"
    },
    {
      "id": "rul_ledger",
      "statement": "The Crown's law forbids keeping maps of old nesting grounds, though possession is punished less severely than sharing.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_skyfall_campaign",
      "name": "The Long Hunt",
      "description": "The realm's lords promised safety from the sky-beasts and paid hunters for every body brought down. A campaign meant to end a season of fear became a generations-long purge.",
      "era": "The Soot Years",
      "location_ids": [
        "loc_cinder_steps",
        "loc_bellwether"
      ]
    },
    {
      "id": "evt_silent_bells",
      "name": "The Quieting",
      "description": "After the last confirmed sighting, the Crown ordered warning bells silenced and public records revised. The official account called the empty skies a victory.",
      "era": "The First Quiet",
      "location_ids": [
        "loc_bellwether",
        "loc_salt_archive"
      ]
    },
    {
      "id": "evt_fen_warmth",
      "name": "A Heat Beneath the Reeds",
      "description": "A Fenkeeper found an egg in a flooded hollow, still warm despite the winter rain. Before dawn, a hairline crack appeared across its shell.",
      "era": "The Present Thaw",
      "location_ids": [
        "loc_morrowfen",
        "loc_hollow_crown"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_hidden_hatchling",
      "name": "The Secret in the Fen",
      "description": "The Fenkeepers want to protect the hatchling, the Scribes want to reveal what the Crown erased, and the Ashwardens are divided between their sworn duty and their growing suspicion. Any public proof could draw hunters to the marsh.",
      "faction_ids": [
        "fac_ashwardens",
        "fac_lantern_scribes",
        "fac_fenkeepers"
      ]
    },
    {
      "id": "cnf_record_and_remnant",
      "name": "The Price of Remembering",
      "description": "The Scribes' recovered testimony may expose the Long Hunt as a deliberate crime, but publishing it could turn grief into vengeance before the hatchling is safe.",
      "faction_ids": [
        "fac_ashwardens",
        "fac_lantern_scribes"
      ]
    }
  ]
}

