{
  "world_id": "wld_vesperhollow",
  "name": "Vesperhollow",
  "description": "Vesperhollow is a world stitched together by the vanished world-shapers, whose oldest works still hum beneath its hills and seas. Their language survives only as pressure in stone and the rhythm of certain winds; no living scholar can speak it. Then a failed initiate named only in rumors answers a buried threshold in that dead tongue. She may be the chosen one the old prophecies promised—or merely the first person able to wake a world that would rather remain asleep. The earnest people of Vesperhollow must decide whether to trust her voice, while rival powers race to shape what it says next.",
  "locations": [
    {
      "id": "loc_ashbell",
      "name": "Ashbell Cloister",
      "description": "A school for mapmakers and ritual apprentices built around a bell that rings only when a student abandons a lesson. Its lowest door bears the sound-pattern that the failed initiate answers."
    },
    {
      "id": "loc_morrowfen",
      "name": "Morrowfen",
      "description": "A reed marsh where the fog repeats fragments of conversations spoken there years earlier. Locals leave wooden name-tags on the water so the echoes do not mistake the living for the dead."
    },
    {
      "id": "loc_seamspire",
      "name": "Seamspire",
      "description": "A narrow black tower rising from a mountain pass, built where two continental plates meet. Its walls shift by a finger's width each season, exposing seams of luminous script."
    },
    {
      "id": "loc_saltarchive",
      "name": "The Salt Archive",
      "description": "A library carved into a dry seabed, where records are pressed into salt tiles. The oldest shelves are kept empty because written words placed there slowly turn into maps."
    },
    {
      "id": "loc_hushwell",
      "name": "Hushwell Basin",
      "description": "A round valley whose streams run uphill toward a silent spring. At its center lies a stone basin believed to hold the world's first unfinished instruction."
    }
  ],
  "factions": [
    {
      "id": "fac_choir_of_measure",
      "name": "Choir of Measure",
      "description": "Surveyors and caretakers who maintain the shapers' remaining structures. They want the initiate to speak carefully, believing each word can alter the land.",
      "location_ids": [
        "loc_seamspire",
        "loc_ashbell"
      ]
    },
    {
      "id": "fac_unwritten",
      "name": "The Unwritten",
      "description": "A fellowship of people whose names have vanished from public records. They seek the dead language to restore their histories, even if the world must be remade around them.",
      "location_ids": [
        "loc_saltarchive",
        "loc_morrowfen"
      ]
    },
    {
      "id": "fac_basinwardens",
      "name": "Basin Wardens",
      "description": "Keepers of Hushwell who believe the unfinished instruction is a restraint, not a command. They protect the basin and distrust anyone who claims to know what the shapers intended.",
      "location_ids": [
        "loc_hushwell"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_speech_alters_stone",
      "statement": "A spoken phrase in the world-shapers' language can alter one nearby feature of the land, but only if the speaker understands the consequence they intend.",
      "category": "metaphysics"
    },
    {
      "id": "rul_echoes_keep_time",
      "statement": "Places remember speech as sound, not meaning; echoes can repeat old words but cannot answer questions or distinguish truth from invention.",
      "category": "metaphysics"
    },
    {
      "id": "rul_names_anchor_memory",
      "statement": "A person's name, spoken by someone who knows them, anchors their memories against being erased from records and recollection.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_empty_maps",
      "statement": "A map left blank in the Salt Archive will gradually acquire the shape of a place that does not yet exist.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_shapers_depart",
      "name": "The Last Measure",
      "description": "The world-shapers completed their final survey and disappeared. Their departure left roads aligned to no known stars and a single instruction unfinished at Hushwell.",
      "era": "Before the Counted Years",
      "location_ids": [
        "loc_hushwell",
        "loc_seamspire"
      ]
    },
    {
      "id": "evt_names_lost",
      "name": "The Quiet Census",
      "description": "A census at Morrowfen recorded several families, then lost every name before dawn. The survivors formed the Unwritten and began preserving their lives in songs and gestures.",
      "era": "Three centuries ago",
      "location_ids": [
        "loc_morrowfen",
        "loc_saltarchive"
      ]
    },
    {
      "id": "evt_bell_answers",
      "name": "The Unfinished Lesson",
      "description": "During an initiation at Ashbell Cloister, a student failed every formal trial but spoke a sound from the sealed threshold. The bell rang once, and a new line appeared on the maps at the Salt Archive.",
      "era": "The Present Turning",
      "location_ids": [
        "loc_ashbell",
        "loc_saltarchive"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_voice_or_vow",
      "name": "Voice or Vow",
      "description": "The Choir of Measure wants to guide the initiate's speech, while the Basin Wardens insist the unfinished instruction must stay unspoken. The initiate must decide whether caution is wisdom or another kind of silence.",
      "faction_ids": [
        "fac_choir_of_measure",
        "fac_basinwardens"
      ]
    },
    {
      "id": "cnf_the_missing_names",
      "name": "The Missing Names",
      "description": "The Unwritten seek a phrase that could restore the names erased from their past. The Choir fears that changing memory on such a scale could also rewrite the living landscape.",
      "faction_ids": [
        "fac_unwritten",
        "fac_choir_of_measure"
      ]
    },
    {
      "id": "cnf_map_of_tomorrow",
      "name": "Map of Tomorrow",
      "description": "A new map has begun forming in the Salt Archive, showing a route to a place no one remembers. Each faction sees a different promise in it, and the initiate's next words may decide which version becomes real.",
      "faction_ids": [
        "fac_unwritten",
        "fac_basinwardens",
        "fac_choir_of_measure"
      ]
    }
  ]
}

